const insertAuthorityTargetNoticeHistory = `-- name: InsertAuthorityTargetNoticeHistory :exec
INSERT INTO seller.authority_target_notice_history (
    order_id, position, seq, notice, notice_note, recheck_on, recorded_at, recorded_by_admin_id, replaced_at, replaced_by_admin_id)
SELECT t.order_id, t.position,
       (SELECT COALESCE(max(h.seq), 0) + 1 FROM seller.authority_target_notice_history h WHERE h.order_id = t.order_id AND h.position = t.position),
       t.notice, t.notice_note, t.recheck_on, t.notice_recorded_at, t.notice_recorded_by_admin_id, $1::timestamptz, $2::bigint
FROM seller.authority_order_targets t
WHERE t.order_id = $3 AND t.position = $4 AND t.notice = 'WITHHELD'
`

type InsertAuthorityTargetNoticeHistoryParams struct {
	Now      time.Time
	AdminID  int64
	OrderID  uuid.UUID
	Position int16
}

// 被取代的暫不告知（從目前列複製，seq 接在最後一列之後）；呼叫方已鎖住來函列。
func (q *Queries) InsertAuthorityTargetNoticeHistory(ctx context.Context, arg InsertAuthorityTargetNoticeHistoryParams) error {
	_, err := q.db.Exec(ctx, insertAuthorityTargetNoticeHistory,
		arg.Now,
		arg.AdminID,
		arg.OrderID,
		arg.Position,
	)
	return err
}

