const lockAuthorityOrder = `-- name: LockAuthorityOrder :one
SELECT id, agency, document_no, received_at, kind, summary, due_at, hold_until, registered_at, registered_by_admin_id, completed_at, completed_by_admin_id, resolution_summary, version, request_id, request_hash, revoked_at, revoked_by_admin_id, revoke_reason
FROM seller.authority_orders
WHERE id = $1
FOR UPDATE
`

// 鎖順序：店家列（被指名的帳號，account_id 升序）、通報列、案件列、詢問列、措施列之後，來函列只由完成與延長鎖。
func (q *Queries) LockAuthorityOrder(ctx context.Context, id uuid.UUID) (SellerAuthorityOrder, error) {
	row := q.db.QueryRow(ctx, lockAuthorityOrder, id)
	var i SellerAuthorityOrder
	err := row.Scan(
		&i.ID,
		&i.Agency,
		&i.DocumentNo,
		&i.ReceivedAt,
		&i.Kind,
		&i.Summary,
		&i.DueAt,
		&i.HoldUntil,
		&i.RegisteredAt,
		&i.RegisteredByAdminID,
		&i.CompletedAt,
		&i.CompletedByAdminID,
		&i.ResolutionSummary,
		&i.Version,
		&i.RequestID,
		&i.RequestHash,
		&i.RevokedAt,
		&i.RevokedByAdminID,
		&i.RevokeReason,
	)
	return i, err
}

const ordersNamingMeasureTarget = `-- name: OrdersNamingMeasureTarget :many
SELECT o.id, (o.revoked_at IS NOT NULL)::boolean AS revoked
FROM seller.authority_orders o
WHERE o.id = ANY($1::uuid[])
  AND EXISTS (
    SELECT 1 FROM seller.authority_order_targets t
    WHERE t.order_id = o.id AND t.account_id = $2 AND (t.store_id IS NULL OR t.store_id = $3))
ORDER BY o.id
FOR SHARE OF o
`

type OrdersNamingMeasureTargetParams struct {
	OrderIds  []uuid.UUID
	AccountID int64
	StoreID   *int64
}

type OrdersNamingMeasureTargetRow struct {
	ID      uuid.UUID
	Revoked bool
}

// 這些來函之中，指名了（帳號 account_id 的）店家 store_id 的：不指定店家的對象帳號的任何店家都算，指定時只算那一家（model.AuthorityOrderTarget.Names）。
// 建立措施驗證來源來函與認定引用的來函用；不存在的來函不會出現在結果裡，revoked 是來函已撤銷登記（不能當作來源）。來函列以 FOR SHARE 鎖住：
// 撤銷登記鎖同一列（FOR UPDATE），所以措施不會在撤銷之後還記成它導出的（鎖順序：呼叫方已鎖住措施帳號的店家列，來函列在後）。
func (q *Queries) OrdersNamingMeasureTarget(ctx context.Context, arg OrdersNamingMeasureTargetParams) ([]OrdersNamingMeasureTargetRow, error) {
	rows, err := q.db.Query(ctx, ordersNamingMeasureTarget, arg.OrderIds, arg.AccountID, arg.StoreID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []OrdersNamingMeasureTargetRow{}
	for rows.Next() {
		var i OrdersNamingMeasureTargetRow
		if err := rows.Scan(&i.ID, &i.Revoked); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const replaceWithheldAuthorityTargetNotice = `-- name: ReplaceWithheldAuthorityTargetNotice :execrows
UPDATE seller.authority_order_targets
SET notice = $1::text, notified_at = $2, notice_note = $3, recheck_on = $4,
    notice_recorded_at = $5, notice_recorded_by_admin_id = $6
WHERE order_id = $7 AND position = $8 AND notice = 'WITHHELD'
`

type ReplaceWithheldAuthorityTargetNoticeParams struct {
	Notice     string
	NotifiedAt *time.Time
	NoticeNote *string
	RecheckOn  *time.Time
	Now        *time.Time
	AdminID    *int64
	OrderID    uuid.UUID
	Position   int16
}

// 把暫不告知的告知換成新的值（已告知或新的確認日期）；只換目前是 WITHHELD 的，被取代的值由呼叫方先寫進歷史。
func (q *Queries) ReplaceWithheldAuthorityTargetNotice(ctx context.Context, arg ReplaceWithheldAuthorityTargetNoticeParams) (int64, error) {
	result, err := q.db.Exec(ctx, replaceWithheldAuthorityTargetNotice,
		arg.Notice,
		arg.NotifiedAt,
		arg.NoticeNote,
		arg.RecheckOn,
		arg.Now,
		arg.AdminID,
		arg.OrderID,
		arg.Position,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const reviewAuthorityOrderByIDs = `-- name: ReviewAuthorityOrderByIDs :many
SELECT r.authority_order_id::uuid AS authority_order_id, r.start_at::timestamptz AS start_at, r.due_at::timestamptz AS due_at
FROM seller.review_authority_order($1::timestamptz) r
WHERE r.authority_order_id = ANY($2::uuid[])
`

type ReviewAuthorityOrderByIDsParams struct {
	At  time.Time
	Ids []uuid.UUID
}

type ReviewAuthorityOrderByIDsRow struct {
	AuthorityOrderID uuid.UUID
	StartAt          time.Time
	DueAt            time.Time
}

// 這些來函的處理期限（資源的 deadline）。規則只有 seller.review_authority_order(at)（objects.sql）；已完成或撤銷的來函沒有列。
// 輸出欄位的轉型是給 sqlc 的（它不型別化複合型別函式的輸出欄位，沒有轉型會在生成時報 column does not exist）。
func (q *Queries) ReviewAuthorityOrderByIDs(ctx context.Context, arg ReviewAuthorityOrderByIDsParams) ([]ReviewAuthorityOrderByIDsRow, error) {
	rows, err := q.db.Query(ctx, reviewAuthorityOrderByIDs, arg.At, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReviewAuthorityOrderByIDsRow{}
	for rows.Next() {
		var i ReviewAuthorityOrderByIDsRow
		if err := rows.Scan(&i.AuthorityOrderID, &i.StartAt, &i.DueAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const revokeAuthorityOrder = `-- name: RevokeAuthorityOrder :one
UPDATE seller.authority_orders
SET revoked_at = $1::timestamptz, revoked_by_admin_id = $2::bigint, revoke_reason = $3::text, version = version + 1
WHERE id = $4 AND completed_at IS NULL AND revoked_at IS NULL AND version = $5
RETURNING id, agency, document_no, received_at, kind, summary, due_at, hold_until, registered_at, registered_by_admin_id, completed_at, completed_by_admin_id, resolution_summary, version, request_id, request_hash, revoked_at, revoked_by_admin_id, revoke_reason
`

type RevokeAuthorityOrderParams struct {
	Now             time.Time
	AdminID         int64
	Reason          string
	ID              uuid.UUID
	ExpectedVersion int64
}

// 撤銷登記（登記錯誤）：只在還沒完成、還沒撤銷而且版本相符時寫入，否則 0 列。保存隨之解除（StoreHolds 不看已撤銷的來函），hold_until 不改（紀錄保留）。
func (q *Queries) RevokeAuthorityOrder(ctx context.Context, arg RevokeAuthorityOrderParams) (SellerAuthorityOrder, error) {
	row := q.db.QueryRow(ctx, revokeAuthorityOrder,
		arg.Now,
		arg.AdminID,
		arg.Reason,
		arg.ID,
		arg.ExpectedVersion,
	)
	var i SellerAuthorityOrder
	err := row.Scan(
		&i.ID,
		&i.Agency,
		&i.DocumentNo,
		&i.ReceivedAt,
		&i.Kind,
		&i.Summary,
		&i.DueAt,
		&i.HoldUntil,
		&i.RegisteredAt,
		&i.RegisteredByAdminID,
		&i.CompletedAt,
		&i.CompletedByAdminID,
		&i.ResolutionSummary,
		&i.Version,
		&i.RequestID,
		&i.RequestHash,
		&i.RevokedAt,
		&i.RevokedByAdminID,
		&i.RevokeReason,
	)
	return i, err
}

